 const load=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(file.size>80*1024*1024)throw Error('ไฟล์ใหญ่เกิน 80 MB');const data=JSON.parse(await file.text());if(data.format!=='idprom-studio'||data.version!==1||data.width!==W||data.height!==H||!Array.isArray(data.layers)||!data.layers.length||data.layers.length>20)throw Error('รูปแบบโปรเจกต์ไม่ถูกต้อง');const next=data.layers.map(l=>{if(typeof l.name!=='string'||typeof l.source!=='string'||![l.x,l.y,l.scale,l.rotation,l.opacity].every(Number.isFinite)||l.scale<.1||l.scale>5||l.opacity<0||l.opacity>1)throw Error('ข้อมูลเลเยอร์ไม่ถูกต้อง');return {...l,id:uid(),visible:!!l.visible,locked:!!l.locked}});let original=null;if(data.compareSource){if(!/^data:image\/(png|jpeg|webp);base64,/.test(data.compareSource))throw Error('รูปต้นฉบับไม่ถูกต้อง');original=await image(data.compareSource);if(original.width>8192||original.height>8192)throw Error('รูปต้นฉบับใหญ่เกินไป')}const previous=historySnapshot();if(await hydrate(next)){compareSourceRef.current=data.compareSource||null;before.current=original;setCompareReady(Boolean(original));setComparing(false);if(data.placement&&['W','H','uX','uY','uW','uH'].every(k=>Number.isFinite(data.placement[k]))&&data.placement.W>0&&data.placement.H>0)placementRef.current=data.placement;undo.current.push(previous);redo.current=[];setRevision(v=>v+1)}}catch(err){setStatus(err.message)}};
